import{_ as e}from"./chunks/27-error-detail-modal.BExjAaM8.js";import{_ as r,o as d,c as o,a2 as a}from"./chunks/framework.z3u3TMv0.js";const m=JSON.parse('{"title":"錯誤代碼排錯","description":"","frontmatter":{"head":[["meta",{"name":"keywords","content":"酒館,AI酒館,Ai酒館,迷你酒館,超迷你酒館,MiniTavern,AI夥伴,AI朋友,Ai本地聊天,Silly Tavern,SillyTavern,手機玩Silly Tavern,Silly Tavern手機版,Silly Tavern安卓,Silly Tavern蘋果,AI角色扮演,角色卡,角色扮演,AI聊天,手機AI,離線AI,AI劇情,本地大模型,本地模型,Ollama,LM Studio,世界書,正則,BYOK,使用手冊,教學,character card,AI roleplay,AI companion"}],["meta",{"property":"og:title","content":"錯誤代碼排錯 · MiniTavern Docs"}],["meta",{"property":"og:description","content":"MiniTavern Ultra guides — mobile AI roleplay, character cards, BYOK, Ollama / LM Studio."}],["meta",{"property":"og:url","content":"https://minitavern.github.io/ultra_guides/zh-TW/manual/errors"}],["link",{"rel":"canonical","href":"https://minitavern.github.io/ultra_guides/zh-TW/manual/errors"}]]},"headers":[],"relativePath":"zh-TW/manual/errors.md","filePath":"zh-TW/manual/errors.md","lastUpdated":1787224147000}'),i={name:"zh-TW/manual/errors.md"};function n(l,t,s,c,u,h){return d(),o("div",null,[...t[0]||(t[0]=[a('<h1 id="錯誤代碼排錯" tabindex="-1">錯誤代碼排錯 <a class="header-anchor" href="#錯誤代碼排錯" aria-label="Permalink to &quot;錯誤代碼排錯&quot;">​</a></h1><p>測連失敗或聊天氣泡報錯時，點 <strong>查看詳情</strong>，對照本頁的<strong>錯誤代碼</strong>（或文案關鍵詞）。</p><p>詳情一般包含：</p><ul><li><strong>錯誤代碼</strong>（英文標識，如 <code>invalidApiKey</code>）</li><li><strong>錯誤原因</strong></li><li><strong>嘗試修復</strong></li></ul><p>下列「代碼」以 App 詳情裡展示的分類名為準（對應 i18n <code>llmTestError.*</code>）。</p><hr><h2 id="快速對照表" tabindex="-1">快速對照表 <a class="header-anchor" href="#快速對照表" aria-label="Permalink to &quot;快速對照表&quot;">​</a></h2><table tabindex="0"><thead><tr><th>錯誤代碼</th><th>用戶可見摘要</th><th>優先處理</th></tr></thead><tbody><tr><td><code>missingApiKey</code></td><td>請先填寫 API 密鑰</td><td>模型連接裡填寫密鑰</td></tr><tr><td><code>invalidApiKey</code></td><td>密鑰無效或過期</td><td>檢查複製是否完整；控制台重新生成</td></tr><tr><td><code>forbidden</code></td><td>訪問被拒絕</td><td>權限、模型是否開通</td></tr><tr><td><code>regionForbidden</code></td><td>地區不可用</td><td>換網絡 / 代理 / 國際站</td></tr><tr><td><code>network</code></td><td>網絡連接失敗</td><td>網絡、Base URL、防火牆</td></tr><tr><td><code>timeout</code></td><td>請求超時</td><td>網絡；本地模型加大超時</td></tr><tr><td><code>modelNotFound</code></td><td>模型不存在</td><td>核對模型 ID</td></tr><tr><td><code>modelRetired</code></td><td>模型已下線</td><td>從列表改選當前可用模型</td></tr><tr><td><code>rateLimit</code></td><td>過於頻繁</td><td>等待後重試</td></tr><tr><td><code>freeTierQuota</code></td><td>免費檔請求配額</td><td>按 Please retry in … 等待；降低頻率或升級付費檔</td></tr><tr><td><code>insufficientQuota</code></td><td>額度不足</td><td>充值 / 換密鑰</td></tr><tr><td><code>spendingCapExceeded</code></td><td>月度消費上限</td><td>控制台提高 spend cap</td></tr><tr><td><code>providerReturnedError</code></td><td>上游返回錯誤</td><td>換模型 / 避開同廠商 <code>:free</code> / OpenRouter BYOK</td></tr><tr><td><code>contextLengthExceeded</code></td><td>上下文超限</td><td>降記憶；回覆令牌設 None；換大上下文模型</td></tr><tr><td><code>anthropicMaxTokensRequired</code></td><td>Claude 缺 max_tokens</td><td>模型設置開啟「回覆令牌」</td></tr><tr><td><code>badRequest</code></td><td>參數有誤</td><td>檢查參數與兼容接口格式</td></tr><tr><td><code>serverError</code></td><td>服務端錯誤</td><td>稍後重試</td></tr><tr><td><code>requestFailed</code></td><td>請求失敗</td><td>看詳情原文</td></tr><tr><td><code>contentPolicy</code></td><td>安全審核未通過</td><td>重生成 / 換模型 / 改寫</td></tr><tr><td><code>emptyContent</code></td><td>回覆為空</td><td>重試；檢查思考模型字段</td></tr><tr><td><code>modelAtCapacity</code></td><td>模型滿載</td><td>等待或換模型</td></tr><tr><td><code>productNotActivated</code></td><td>產品未開通</td><td>控制台開通模型</td></tr><tr><td><code>visionUnsupported</code></td><td>不支持圖片</td><td>換視覺模型或關附圖</td></tr><tr><td><code>textOutputUnsupported</code></td><td>不支持文字對話</td><td>改選文本聊天模型，勿選 TTS/生圖專用 ID</td></tr></tbody></table><hr><h2 id="分類詳解" tabindex="-1">分類詳解 <a class="header-anchor" href="#分類詳解" aria-label="Permalink to &quot;分類詳解&quot;">​</a></h2><h3 id="missingapikey" tabindex="-1">missingApiKey <a class="header-anchor" href="#missingapikey" aria-label="Permalink to &quot;missingApiKey&quot;">​</a></h3><ul><li><strong>現象</strong>：未填密鑰無法請求。</li><li><strong>處理</strong>：設置 → 模型連接 → 填寫 API 密鑰。本地 Ollama 等可填佔位字符（若校驗非空）。</li></ul><h3 id="invalidapikey" tabindex="-1">invalidApiKey <a class="header-anchor" href="#invalidapikey" aria-label="Permalink to &quot;invalidApiKey&quot;">​</a></h3><ul><li><strong>現象</strong>：401 類、密鑰無效。</li><li><strong>處理</strong>：無空格完整複製；確認國內/國際站與密鑰匹配；重新生成密鑰。</li></ul><h3 id="forbidden-regionforbidden" tabindex="-1">forbidden / regionForbidden <a class="header-anchor" href="#forbidden-regionforbidden" aria-label="Permalink to &quot;forbidden / regionForbidden&quot;">​</a></h3><ul><li><strong>現象</strong>：403、地區限制。</li><li><strong>處理</strong>：確認模型權限；換代理或國際站 Base URL。</li></ul><h3 id="network-timeout" tabindex="-1">network / timeout <a class="header-anchor" href="#network-timeout" aria-label="Permalink to &quot;network / timeout&quot;">​</a></h3><ul><li><strong>現象</strong>：連不上或長時間無響應。</li><li><strong>處理</strong>： <ul><li>檢查 Base URL（本地勿用手機上的 <code>localhost</code>，用電腦局域網 IP）。</li><li>電腦防火牆放行端口；手機與電腦同一 Wi‑Fi。</li><li>弱網或本地慢模型：增大超時、換小模型。</li></ul></li></ul><h3 id="modelnotfound" tabindex="-1">modelNotFound <a class="header-anchor" href="#modelnotfound" aria-label="Permalink to &quot;modelNotFound&quot;">​</a></h3><ul><li><strong>現象</strong>：模型 ID 錯誤。</li><li><strong>處理</strong>：測連後從列表重選；本地與 <code>ollama list</code> / LM Studio 顯示名一致。</li></ul><h3 id="modelretired" tabindex="-1">modelRetired <a class="header-anchor" href="#modelretired" aria-label="Permalink to &quot;modelRetired&quot;">​</a></h3><ul><li><strong>現象</strong>：HTTP 404，文案含 <code>no longer available to new users</code> / <code>use a newer model</code>（如 <code>models/gemini-2.5-flash-lite</code>）。</li><li><strong>區別</strong>：模型已被服務商停用或不再向新用戶開放，不是拼寫錯誤。</li><li><strong>處理</strong>：模型連接里拉取最新列表，改選仍在線的 Gemini（如 <code>gemini-flash-latest</code>）。不必改用 Interactions API。目錄：<a href="https://ai.google.dev/gemini-api/docs/models" target="_blank" rel="noreferrer">Gemini models</a>。</li></ul><h3 id="ratelimit" tabindex="-1">rateLimit <a class="header-anchor" href="#ratelimit" aria-label="Permalink to &quot;rateLimit&quot;">​</a></h3><ul><li><strong>處理</strong>：降低發送頻率；稍後重試；升級套餐。</li></ul><h3 id="freetierquota" tabindex="-1">freeTierQuota <a class="header-anchor" href="#freetierquota" aria-label="Permalink to &quot;freeTierQuota&quot;">​</a></h3><ul><li><strong>現象</strong>：Gemini 等返回 <code>HTTP 429</code> + <code>generate_content_free_tier_requests</code>（常見 limit: 20），並提示 <code>Please retry in …s</code>。</li><li><strong>區別</strong>：這是<strong>免費檔每分鐘/每天請求次數</strong>，不是賬戶沒錢，也不是項目月度 spend cap。</li><li><strong>處理</strong>：等待提示秒數後重試；降低發送頻率；到 <a href="https://ai.dev/rate-limit" target="_blank" rel="noreferrer">AI Studio 用量</a> 查看；需要更高限額則開通結算/升級付費檔。說明：<a href="https://ai.google.dev/gemini-api/docs/rate-limits" target="_blank" rel="noreferrer">Gemini rate limits</a>。</li></ul><h3 id="insufficientquota-spendingcapexceeded" tabindex="-1">insufficientQuota / spendingCapExceeded <a class="header-anchor" href="#insufficientquota-spendingcapexceeded" aria-label="Permalink to &quot;insufficientQuota / spendingCapExceeded&quot;">​</a></h3><ul><li><strong>區別</strong>：額度用盡 vs <strong>項目月度消費上限</strong>（後者稍後重試通常無效）。</li><li><strong>處理</strong>：充值；或到控制台調整 spend cap（如 Google AI Studio Spend 頁）。</li></ul><h3 id="providerreturnederror" tabindex="-1">providerReturnedError <a class="header-anchor" href="#providerreturnederror" aria-label="Permalink to &quot;providerReturnedError&quot;">​</a></h3><ul><li><strong>現象</strong>：OpenRouter 等返回 <code>HTTP 429: Provider returned error</code>（<code>:free</code> 模型常見）。</li><li><strong>處理</strong>：稍後重試；換其他廠商空閒模型；或 <a href="https://openrouter.ai/settings/integrations" target="_blank" rel="noreferrer">OpenRouter BYOK</a>。</li></ul><h3 id="contextlengthexceeded" tabindex="-1">contextLengthExceeded <a class="header-anchor" href="#contextlengthexceeded" aria-label="Permalink to &quot;contextLengthExceeded&quot;">​</a></h3><ul><li><strong>處理</strong>：設置 → 模型設置 → 減小記憶長度；將「回覆令牌」設為 None（若適用）；換更大上下文模型。</li></ul><h3 id="anthropicmaxtokensrequired" tabindex="-1">anthropicMaxTokensRequired <a class="header-anchor" href="#anthropicmaxtokensrequired" aria-label="Permalink to &quot;anthropicMaxTokensRequired&quot;">​</a></h3><ul><li><strong>處理</strong>：Claude 必須帶 max_tokens → 模型設置中開啟「回覆令牌」，不要設為 None。</li></ul><h3 id="badrequest" tabindex="-1">badRequest <a class="header-anchor" href="#badrequest" aria-label="Permalink to &quot;badRequest&quot;">​</a></h3><ul><li><strong>處理</strong>：檢查 temperature 等參數；第三方兼容站是否真兼容 OpenAI/Anthropic 格式。</li></ul><h3 id="servererror-requestfailed-modelatcapacity" tabindex="-1">serverError / requestFailed / modelAtCapacity <a class="header-anchor" href="#servererror-requestfailed-modelatcapacity" aria-label="Permalink to &quot;serverError / requestFailed / modelAtCapacity&quot;">​</a></h3><ul><li><strong>處理</strong>：稍後重試；換端點或模型；持續失敗聯繫服務商並附詳情原文。</li></ul><h3 id="contentpolicy" tabindex="-1">contentPolicy <a class="header-anchor" href="#contentpolicy" aria-label="Permalink to &quot;contentPolicy&quot;">​</a></h3><ul><li><strong>處理</strong>：重生成、改寫、換審核更松的模型；部分 NSFW 卡易觸發輸出攔截。</li></ul><h3 id="emptycontent" tabindex="-1">emptyContent <a class="header-anchor" href="#emptycontent" aria-label="Permalink to &quot;emptyContent&quot;">​</a></h3><ul><li><strong>處理</strong>：重試；部分思考模型只返回 reasoning → 看詳情中的完整字段或換模型。</li></ul><h3 id="productnotactivated" tabindex="-1">productNotActivated <a class="header-anchor" href="#productnotactivated" aria-label="Permalink to &quot;productNotActivated&quot;">​</a></h3><ul><li><strong>處理</strong>：雲廠商控制台開通對應產品/模型後再用當前密鑰。</li></ul><h3 id="visionunsupported" tabindex="-1">visionUnsupported <a class="header-anchor" href="#visionunsupported" aria-label="Permalink to &quot;visionUnsupported&quot;">​</a></h3><ul><li><strong>處理</strong>：換支持視覺的模型；或不要發圖 / 開啟識圖描寫流程改用純文本描寫。</li></ul><h3 id="textoutputunsupported" tabindex="-1">textOutputUnsupported <a class="header-anchor" href="#textoutputunsupported" aria-label="Permalink to &quot;textOutputUnsupported&quot;">​</a></h3><ul><li><strong>現象</strong>：HTTP 400，文案含 <code>response modalities</code> 且 <code>TEXT</code> 不受支持（如 <code>models/gemini-2.5-flash-preview-tts</code> 只接受 <code>AUDIO</code>）。</li><li><strong>區別</strong>：選了語音合成 / 生圖等專用模型做聊天測連，不是密鑰或採樣參數填錯。</li><li><strong>處理</strong>：模型連接裡改選文本聊天模型（如 <code>gemini-flash-latest</code>）。不要選名稱帶 <code>tts</code>、<code>image</code> 的專用 ID。語音、生圖請到對應功能裡配置。</li></ul><hr><h2 id="服務層錯誤碼-進階" tabindex="-1">服務層錯誤碼（進階） <a class="header-anchor" href="#服務層錯誤碼-進階" aria-label="Permalink to &quot;服務層錯誤碼（進階）&quot;">​</a></h2><p>底層還可能出現 <code>LlmErrorCode</code>（日誌 / 開發向）：</p><table tabindex="0"><thead><tr><th>代碼</th><th>含義</th></tr></thead><tbody><tr><td><code>REQUEST_FAILED</code></td><td>非流式 HTTP 失敗</td></tr><tr><td><code>STREAM_FAILED</code></td><td>流式失敗</td></tr><tr><td><code>REQUEST_CANCELLED</code></td><td>用戶取消</td></tr><tr><td><code>INVALID_CONFIG</code></td><td>配置無效</td></tr><tr><td><code>GET_MODELS_FAILED</code></td><td>拉模型列表失敗</td></tr><tr><td><code>TEST_CONNECTION_FAILED</code></td><td>測連失敗</td></tr><tr><td><code>PARSE_FAILED</code></td><td>響應解析失敗</td></tr><tr><td><code>UNKNOWN</code></td><td>未分類</td></tr></tbody></table><p>用戶側請優先看詳情裡的分類名（上一節），不必強記本表。</p><hr><h2 id="本地模型專項" tabindex="-1">本地模型專項 <a class="header-anchor" href="#本地模型專項" aria-label="Permalink to &quot;本地模型專項&quot;">​</a></h2><p>連不上電腦上的 Ollama / LM Studio：見 <a href="/ultra_guides/zh-TW/troubleshoot">本地模型排錯</a>。</p><p>App 測連 / 聊天報錯（含錯誤代碼）：見 <a href="/ultra_guides/zh-TW/manual/errors">使用手冊 · 錯誤代碼排錯</a>。</p><div class="tip custom-block"><p class="custom-block-title">截圖</p><p><img src="'+e+'" alt="錯誤詳情"></p></div>',58)])])}const b=r(i,[["render",n]]);export{m as __pageData,b as default};
